def find(shape,grid,colors):
    H=max(r for r,c in shape);W=max(c for r,c in shape)
    R=len(grid);C=len(grid[0])
    res=[]
    for r0 in range(R-H):
        for c0 in range(C-W):
            t=frozenset((r0+r,c0+c) for r,c in shape)
            if all(grid[r][c] in colors for r,c in t):
                res.append(t)
    return res
